### OpenClaw (Unbrowse) workflow
- Authenticate in the browser first (no credentials are shipped with this skill).
- Capture fresh auth locally: run `unbrowse_capture` on an authenticated page for this domain.
- Execute via backend gate + client browser executor: `unbrowse_replay` with `executionMode="backend"`.

Example:
```text
unbrowse_replay { service: "yellowpages", executionMode: "backend", endpoint: "GET /claim-your-business" }
```

```typescript
// Check if a business is claimable and get instructions.
async function checkClaimEligibility(businessId: string) {
  try {
    const response = await client.claimYourBusiness({ businessId });
    if (response.isClaimable) {
      console.log("Business is claimable. Follow these instructions:", response.instructions);
    } else {
      console.log("Business is not currently claimable.");
    }
    return response;
  } catch (error) {
    console.error("Error checking claim eligibility:", error);
    return null;
  }
}
```

